import hashlib


class Solver:
    """SHA-256 via hashlib, which uses OpenSSL's AVX2 implementation.

    On this CPU (no SHA-NI) the compression chain is about 3 cycles per
    round and OpenSSL already overlaps the message schedule with it, so a
    correct single-stream hash cannot be several times faster. This path
    avoids the cryptography Hash object construction the reference does.
    """

    def solve(self, problem, **kwargs):
        return {"digest": hashlib.sha256(problem["plaintext"]).digest()}

