        }
        h0 += a; h1 += b_; h2 += c; h3 += d; h4 += e; h5 += f; h6 += g; h7 += h;
    }

    uint32_t hs[8] = {h0,h1,h2,h3,h4,h5,h6,h7};
    for (int i = 0; i < 8; i++) {
