#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <openssl/sha.h>

static double now(void) {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

typedef struct {
    const uint8_t *data;
    size_t len;
    uint8_t out[32];
} job;

static void *worker(void *arg) {
    job *j = arg;
    SHA256(j->data, j->len, j->out);
    return NULL;
}

int main(void) {
    size_t n = 20ull<<20;
    uint8_t *buf = malloc(n);
    memset(buf, 0x5a, n);
    uint8_t out[32];
    int reps = 3;
    double t0 = now();
    for (int r=0;r<reps;r++) SHA256(buf, n, out);
    double sec = (now()-t0)/reps;
    printf("1 thread: %.4f s  %.1f MB/s\n", sec, (n/1e6)/sec);

    for (int threads = 2; threads <= 6; threads++) {
        job *jobs = calloc(threads, sizeof(job));
        pthread_t *ths = calloc(threads, sizeof(pthread_t));
        size_t chunk = n / threads;
        t0 = now();
        for (int r=0;r<reps;r++) {
            for (int t=0;t<threads;t++) {
                jobs[t].data = buf + t*chunk;
                jobs[t].len = (t==threads-1) ? (n - t*chunk) : chunk;
                pthread_create(&ths[t], NULL, worker, &jobs[t]);
            }
            uint32_t acc=0;
            for (int t=0;t<threads;t++) {
                pthread_join(ths[t], NULL);
                acc += jobs[t].out[0];
            }
            if (acc==0xFFFFFFFF) printf("x");
        }
        sec = (now()-t0)/reps;
        printf("%d threads: %.4f s  %.1f MB/s  (%.2fx)\n", threads, sec, (n/1e6)/sec, (0.0482/sec));
        free(jobs); free(ths);
    }
    free(buf);
    return 0;
}
