{"command":"cat > bench_pool.c << 'EOF'
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <openssl/sha.h>

#define T 6
static const uint8_t *g_data;
static size_t g_len;
static uint8_t g_out[T][32];
static pthread_t th[T];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int go_epoch = 0;
static int done_count = 0;
static int stop = 0;

static void *worker(void *arg) {
    long id = (long)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (go_epoch == seen && !stop) pthread_cond_wait(&cv_go, &mu);
        if (stop) { pthread_mutex_unlock(&mu); break; }
        seen = go_epoch;
        pthread_mutex_unlock(&mu);
        size_t chunk = g_len / T;
        size_t off = id * chunk;
        size_t len = (id == T-1) ? (g_len - off) : chunk;
        SHA256(g_data + off, len, g_out[id]);
        pthread_mutex_lock(&mu);
        done_count++;
        if (done_count == T) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
    return NULL;
}

static double now(void) {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

int main(void) {
    size_t n = 20ull<<20;
    uint8_t *buf = malloc(n);
    memset(buf, 0x5a, n);
    for (long i = 0; i < T; i++) pthread_create(&th[i], NULL, worker, (void*)i);
    /* warmup */
    g_data = buf; g_len = n;
    pthread_mutex_lock(&mu);
    done_count = 0; go_epoch++;
    pthread_cond_broadcast(&cv_go);
    while (done_count < T) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);

    int reps = 5;
    double t0 = now();
    uint32_t acc = 0;
    for (int r = 0; r < reps; r++) {
        pthread_mutex_lock(&mu);
        done_count = 0; go_epoch++;
        pthread_cond_broadcast(&cv_go);
        while (done_count < T) pthread_cond_wait(&cv_done, &mu);
        pthread_mutex_unlock(&mu);
        acc += g_out[0][0];
    }
    double sec = (now()-t0)/reps;
    printf("pool %d threads: %.4f s  %.1f MB/s acc=%u\n", T, sec, (n/1e6)/sec, acc);

    /* also single */
    uint8_t out[32];
    t0 = now();
    for (int r = 0; r < reps; r++) SHA256(buf, n, out);
    sec = (now()-t0)/reps;
    printf("single: %.4f s  %.1f MB/s\n", sec, (n/1e6)/sec);

    pthread_mutex_lock(&mu); stop = 1; go_epoch++; pthread_cond_broadcast(&cv_go); pthread_mutex_unlock(&mu);
    for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
    free(buf);
    return 0;
}
EOF
