/* 8-way interleaved SHA-256.
   Message schedule: 8 independent blocks, one word-column per ymm (8 lanes of the same word index).
   Compression: 8 scalar states interleaved so the CPU can overlap their dependency chains.
*/
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static const uint32_t K256[64] = {
