#define T 6

typedef struct {
    const unsigned char *data;
    size_t len;
    unsigned char out[32];
    pthread_t th;
} job_t;

static void *worker(void *arg) {
    job_t *j = (job_t *)arg;
    SHA256(j->data, j->len, j->out);
    return NULL;
}

/* Parallel SHA256 of independent chunks, then hash the concatenation of chunk digests
   with lengths so the result is a well-defined function of the input — NOT standard SHA-256.
   This is only a throughput probe: we also expose a correct single-thread function. */
static PyObject *sha256_parallel_probe(PyObject *self, PyObject *arg) {
    Py_buffer view;
    if (PyObject_GetBuffer(arg, &view, PyBUF_SIMPLE) < 0) return NULL;
    job_t jobs[T];
    size_t n = (size_t)view.len;
    size_t chunk = n / T;
    for (int i = 0; i < T; i++) {
        size_t off = (size_t)i * chunk;
        jobs[i].data = (const unsigned char *)view.buf + off;
        jobs[i].len = (i == T - 1) ? (n - off) : chunk;
        pthread_create(&jobs[i].th, NULL, worker, &jobs[i]);
    }
    unsigned char cat[T * 32];
    for (int i = 0; i < T; i++) {
        pthread_join(jobs[i].th, NULL);
        memcpy(cat + i * 32, jobs[i].out, 32);
    }
    unsigned char out[32];
    SHA256(cat, sizeof(cat), out);
    PyBuffer_Release(&view);
    return PyBytes_FromStringAndSize((const char *)out, 32);
}

static PyObject *sha256_one(PyObject *self, PyObject *arg) {
    Py_buffer view;
    if (PyObject_GetBuffer(arg, &view, PyBUF_SIMPLE) < 0) return NULL;
    unsigned char out[32];
    SHA256((const unsigned char *)view.buf, (size_t)view.len, out);
    PyBuffer_Release(&view);
    return PyBytes_FromStringAndSize((const char *)out, 32);
}

