/* calibrate TSC frequency with clock_gettime */
#include <time.h>
static double tsc_hz(void) {
    struct timespec a, b;
    uint64_t t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &a);
    t0 = rdtsc();
    /* busy wait ~200ms */
    do { clock_gettime(CLOCK_MONOTONIC, &b); }
    while ((b.tv_sec - a.tv_sec) + (b.tv_nsec - a.tv_nsec)/1e9 < 0.20);
    t1 = rdtsc();
    double sec = (b.tv_sec - a.tv_sec) + (b.tv_nsec - a.tv_nsec)/1e9;
    return (t1 - t0) / sec;
}

