{"command":"cat > sha256_intel2.c << 'EOF'
/* Single-stream SHA-256 using the Intel 2-block AVX2 message schedule
   (same structure as OpenSSL/Linux sha256-avx2) with scalar BMI2-style rounds
   interleaved across the two blocks' schedules... 

   Actually for ONE stream the two ymm lanes hold consecutive blocks of the SAME
   message, but the second block's compression depends on the first block's output.
   The schedule can still be computed for both blocks in parallel (schedule does not
   depend on the chaining value). Then compression of block 2 must wait for block 1.

   That only overlaps schedule of block N+1 with compression of block N, which
   OpenSSL already does. This file measures just the schedule+compress of a
   hand-written version to see if we can beat 6 cyc/byte.

   Strategy: compute schedule for 2 consecutive blocks with AVX2 (independent),
   store K+W, then compress block 0 then block 1 with a tight scalar loop using rorx.
*/
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

static const uint32_t K256[64] __attribute__((aligned(64))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

/* K duplicated in both lanes, groups of 4 */
static uint32_t K2[16][8] __attribute__((aligned(64)));
static void initk(void){
    for(int i=0;i<16;i++) for(int lane=0;lane<2;lane++) for(int j=0;j<4;j++)
        K2[i][lane*4+j]=K256[i*4+j];
}

static inline __m256i sig0(__m256i x){
    __m256i r7=_mm256_or_si256(_mm256_srli_epi32(x,7),_mm256_slli_epi32(x,25));
    __m256i r18=_mm256_or_si256(_mm256_srli_epi32(x,18),_mm256_slli_epi32(x,14));
    return _mm256_xor_si256(_mm256_xor_si256(r7,r18),_mm256_srli_epi32(x,3));
}
static inline __m256i sig1(__m256i x){
    __m256i r17=_mm256_or_si256(_mm256_srli_epi32(x,17),_mm256_slli_epi32(x,15));
    __m256i r19=_mm256_or_si256(_mm256_srli_epi32(x,19),_mm256_slli_epi32(x,13));
    return _mm256_xor_si256(_mm256_xor_si256(r17,r19),_mm256_srli_epi32(x,10));
}

#define RORX(x,n) __rorl((x),(n))

static inline void compress(uint32_t H[8], const uint32_t kw[64]) {
    uint32_t a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    #pragma clang loop unroll(full)
    for (int i=0;i<64;i++) {
        uint32_t S1 = RORX(e,6) ^ RORX(e,11) ^ RORX(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + kw[i];
        uint32_t S0 = RORX(a,2) ^ RORX(a,13) ^ RORX(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    H[0]+=a; H[1]+=b; H[2]+=c; H[3]+=d; H[4]+=e; H[5]+=f; H[6]+=g; H[7]+=h;
}

/* Schedule 2 consecutive blocks, write kw0[64], kw1[64] = W+K */
static void schedule2(const uint8_t *blk0, const uint8_t *blk1, uint32_t kw0[64], uint32_t kw1[64]) {
    const __m256i bswap = _mm256_setr_epi8(
        3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12,
        3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12);
    __m128i p0=_mm_loadu_si128((const __m128i*)(blk0+0));
    __m128i p1=_mm_loadu_si128((const __m128i*)(blk0+16));
    __m128i p2=_mm_loadu_si128((const __m128i*)(blk0+32));
    __m128i p3=_mm_loadu_si128((const __m128i*)(blk0+48));
    __m128i q0=_mm_loadu_si128((const __m128i*)(blk1+0));
    __m128i q1=_mm_loadu_si128((const __m128i*)(blk1+16));
    __m128i q2=_mm_loadu_si128((const __m128i*)(blk1+32));
    __m128i q3=_mm_loadu_si128((const __m128i*)(blk1+48));
    __m256i w[16];
    w[0]=_mm256_shuffle_epi8(_mm256_inserti128_si256(_mm256_castsi128_si256(p0),q0,1), bswap);
    w[1]=_mm256_shuffle_epi8(_mm256_inserti128_si256(_mm256_castsi128_si256(p1),q1,1), bswap);
    w[2]=_mm256_shuffle_epi8(_mm256_inserti128_si256(_mm256_castsi128_si256(p2),q2,1), bswap);
    w[3]=_mm256_shuffle_epi8(_mm256_inserti128_si256(_mm256_castsi128_si256(p3),q3,1), bswap);
    for (int i=4;i<16;i++) {
        __m256i wm16=w[i-4];
        __m256i wm15=_mm256_alignr_epi8(w[i-3], w[i-4], 4);
        __m256i wm7 =_mm256_alignr_epi8(w[i-1], w[i-2], 4);
        __m256i wm2 =_mm256_srli_si256(w[i-1], 8);
        __m256i s0=sig0(wm15);
        __m256i partial=_mm256_add_epi32(_mm256_add_epi32(wm16,s0), wm7);
        __m256i low=_mm256_add_epi32(partial, sig1(wm2));
        __m256i rep=_mm256_shuffle_epi32(low, 0x44);
        __m256i high=_mm256_add_epi32(partial, sig1(rep));
        w[i]=_mm256_blend_epi32(low, high, 0xCC);
    }
    uint32_t tmp[8] __attribute__((aligned(32)));
    for (int i=0;i<16;i++) {
        _mm256_store_si256((__m256i*)tmp, _mm256_add_epi32(w[i], _mm256_load_si256((const __m256i*)K2[i])));
        kw0[4*i]=tmp[0]; kw0[4*i+1]=tmp[1]; kw0[4*i+2]=tmp[2]; kw0[4*i+3]=tmp[3];
        kw1[4*i]=tmp[4]; kw1[4*i+1]=tmp[5]; kw1[4*i+2]=tmp[6]; kw1[4*i+3]=tmp[7];
    }
}

void sha256_fast(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t H[8] = {0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,
                     0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};
    size_t nblocks = len >> 6;
    size_t pairs = nblocks >> 1;
    const uint8_t *p = data;
    uint32_t kw0[64], kw1[64];
    for (size_t i=0;i<pairs;i++) {
        schedule2(p, p+64, kw0, kw1);
        compress(H, kw0);
        compress(H, kw1);
        p += 128;
    }
    if (nblocks & 1) {
        /* one leftover full block: duplicate into lane1 (ignored) */
        uint8_t dummy[64] = {0};
        schedule2(p, dummy, kw0, kw1);
        compress(H, kw0);
        p += 64;
    }
    /* padding */
    uint8_t block[128];
    size_t rem = len & 63;
    memset(block, 0, sizeof(block));
    if (rem) memcpy(block, p, rem);
    block[rem] = 0x80;
    size_t pad_blocks = (rem + 9 <= 64) ? 1 : 2;
    uint64_t bitlen = (uint64_t)len << 3;
    for (int i=7;i>=0;i--) { block[pad_blocks*64 - 8 + i] = (uint8_t)bitlen; bitlen >>= 8; }
    if (pad_blocks == 1) {
        uint8_t dummy[64]={0};
        schedule2(block, dummy, kw0, kw1);
        compress(H, kw0);
    } else {
        schedule2(block, block+64, kw0, kw1);
        compress(H, kw0);
        compress(H, kw1);
    }
    for (int i=0;i<8;i++) {
        uint32_t v=__builtin_bswap32(H[i]);
        memcpy(out+4*i, &v, 4);
    }
}

static double now(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}

int main(void){
    initk();
    /* correctness small */
    const char *abc="abc";
    uint8_t out[32], ref[32];
    sha256_fast((const uint8_t*)abc, 3, out);
    SHA256((const uint8_t*)abc, 3, ref);
    printf("abc %s\n", memcmp(out,ref,32)==0?"YES":"NO");

    size_t n=20ull<<20;
    uint8_t *buf=malloc(n);
    for(size_t i=0;i<n;i++) buf[i]=(uint8_t)(i*131u+7);
    sha256_fast(buf, n, out);
    SHA256(buf, n, ref);
    printf("20MB match %s\n", memcmp(out,ref,32)==0?"YES":"NO");
    if (memcmp(out,ref,32)) {
        printf("got "); for(int i=0;i<32;i++) printf("%02x", out[i]); printf("\n");
        printf("ref "); for(int i=0;i<32;i++) printf("%02x", ref[i]); printf("\n");
        return 1;
    }
    int reps=3;
    double t0=now();
    for(int r=0;r<reps;r++) sha256_fast(buf,n,out);
    double sec=(now()-t0)/reps;
    printf("ours:    %.4f s  %.1f MB/s\n", sec, (n/1e6)/sec);
    t0=now();
    for(int r=0;r<reps;r++) SHA256(buf,n,ref);
    sec=(now()-t0)/reps;
    printf("openssl: %.4f s  %.1f MB/s\n", sec, (n/1e6)/sec);
    free(buf);
    return 0;
}
